insert into public.game_config (key, value) values ('flavour', '{"moods":{"thriving":"{name} {is} wind-flushed and wild with joy.","happy":"{name} {is} mending a net on the step, watching the boats.","sleepy":"{name} keeps yawning at the waves. The hammock is swaying hopefully.","hungry":"{name} {is} eyeing the chowder pot like a gull eyes a chip.","bored":"{name} {is} skimming stones and sighing. Time for a swim or a story.","magical":"{name} {is} humming with sea magic. The tide is listening.","offended":"{name} {has} turned up {their} collar and walked off down the shore. Give {them} a while and a hot drink."},"joined":"{name} has joined the coven. The tide brought someone good.","ritualComplete":"The sea went very quiet, then very loud.","dailyTitle":"Washed up on the step","dailyBody":"Waiting by the door at low tide: today''s driftstones and a small find from the shore.","welcome":"The shore is yours, {name}"}'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.game_config (key, value) values ('shared_events', '{"lantern_circle":{"name":"Lantern Circle","locationId":"spring","minParticipants":2,"effects":{"magic":30,"social":25,"joy":10},"coins":30,"xp":25,"lootItemId":"col_amber_bead"},"tea_leaf_supper":{"name":"Tea Leaf Supper","locationId":"terrace","minParticipants":2,"effects":{"magic":25,"energy":20,"social":20},"coins":25,"xp":20,"lootItemId":"col_old_coin"},"full_moon":{"name":"Full Moon Ceremony","locationId":"deck","minParticipants":2,"effects":{"magic":40,"social":30,"joy":20},"coins":60,"xp":40,"lootItemId":"col_full_moon","moonPhase":"full"},"new_moon":{"name":"New Moon Intentions","locationId":"deck","minParticipants":2,"effects":{"magic":35,"energy":20,"social":25},"coins":50,"xp":35,"lootItemId":"col_new_moon","moonPhase":"new"}}'::jsonb) on conflict (key) do update set value = excluded.value;
insert into public.game_config (key, value) values ('gift_treats', '[{"id":"treat_tea","name":"Strong builder''s tea","cost":8,"effects":{"nourishment":15,"joy":15,"energy":10}},{"id":"treat_chowder","name":"Smoky chowder","cost":6,"effects":{"nourishment":30,"energy":5}},{"id":"treat_bread","name":"Seaweed bread","cost":5,"effects":{"nourishment":25,"joy":8}},{"id":"treat_thrift","name":"Sea thrift posy","cost":10,"effects":{"joy":25,"magic":5}}]'::jsonb) on conflict (key) do update set value = excluded.value;
